-- ==============================================================================
-- WeMade ERP — Persist tenant business model & seed real pipeline topologies
-- ==============================================================================
-- Fixes two defects introduced alongside the dynamic pipeline feature:
--
-- 1. `tenants.business_preset` did not exist, so a tenant's garment business model
--    (FOB / CMT / Brand D2C) was never persisted and every tenant was provisioned
--    from the global default preset regardless of what it actually is.
--
-- 2. `tenant_pipelines.graph_data` was seeded as `{"tenantId":...,"company":...}`
--    with no `nodes` or `edges`. Because the row existed, the read path returned a
--    pipeline with zero nodes instead of provisioning one, leaving the factory flow
--    canvas empty for all three demo tenants.
--
-- The topologies below are generated from PipelinePresetFactory by
-- `GenerateSeedTopologyTool`, and `SeedTopologyConsistencyTest` asserts this file
-- still matches that factory, so the seed cannot silently drift from the code.
-- ==============================================================================

-- 1. Persist the tenant's business model.
ALTER TABLE tenants
    ADD COLUMN IF NOT EXISTS business_preset VARCHAR(50) NOT NULL DEFAULT 'fob_full_package';

UPDATE tenants SET business_preset = 'fob_full_package' WHERE id = 'ten-demo-001';
UPDATE tenants SET business_preset = 'cmt_makloon'      WHERE id = 'ten-demo-cmt';
UPDATE tenants SET business_preset = 'brand_d2c'        WHERE id = 'ten-demo-d2c';

-- 2. The D2C demo tenant runs a tenant-only plugin module (screen printing / embroidery)
--    on top of the nine built-ins. Custom modules and a module count above nine both
--    require the Enterprise plan, so align the seeded plan with the seeded topology.
UPDATE tenants SET tier = 'ENTERPRISE' WHERE id = 'ten-demo-d2c';

-- 3. Make sure a pipeline row exists for each demo tenant before it is populated.
INSERT INTO tenant_pipelines (id, tenant_id, pipeline_name, base_preset, graph_data)
VALUES
    ('pipe-ten-demo-001', 'ten-demo-001', 'Alur Operasional', 'fob_full_package', '{}'),
    ('pipe-ten-demo-cmt', 'ten-demo-cmt', 'Alur Operasional', 'cmt_makloon',      '{}'),
    ('pipe-ten-demo-d2c', 'ten-demo-d2c', 'Alur Operasional', 'brand_d2c',        '{}')
ON CONFLICT (tenant_id) DO NOTHING;

-- 4. Seeded topologies. Each tenant renames modules in its own words, switches
--    different modules off, and carries its own costing parameters.
-- PT WeMade Garmen Ekspor — FOB Full Package: 9 node / 12 edge (9 aktif, 0 bypass, 0 plugin kustom)
