meters":{},"isCustomPlugin":false,"configSchemaJson":null},{"nodeId":"fob-fulfillment","moduleId":"fulfillment","customDisplayName":"Ekspedisi Ekspor & Dokumen B/L","archetype":"fulfillment","isBypassed":false,"stepOrderIndex":9,"customFormulaParameters":{},"isCustomPlugin":false,"configSchemaJson":null}],"edges":[{"edgeId":"edge-fob-crm-sales-to-fob-sampling","fromNodeId":"fob-crm-sales","toNodeId":"fob-sampling","expectedDataType":"StandardHandoffPayload","isFeedbackReworkLoop":false},{"edgeId":"edge-fob-sampling-to-fob-tech-pack","fromNodeId":"fob-sampling","toNodeId":"fob-tech-pack","expectedDataType":"StandardHandoffPayload","isFeedbackReworkLoop":false},{"edgeId":"edge-fob-tech-pack-to-fob-inventory","fromNodeId":"fob-tech-pack","toNodeId":"fob-inventory","expectedDataType":"StandardHandoffPayload","isFeedbackReworkLoop":false},{"edgeId":"edge-fob-tech-pack-to-fob-costing-hpp","fromNodeId":"fob-tech-pack","toNodeId":"fob-costing-hpp","expectedDataType":"StandardHandoffPayload","isFeedbackReworkLoop":false},{"edgeId":"edge-fob-inventory-to-fob-costing-hpp","fromNodeId":"fob-inventory","toNodeId":"fob-costing-hpp","expectedDataType":"StandardHandoffPayload","isFeedbackReworkLoop":false},{"edgeId":"edge-fob-inventory-to-fob-mrp-spk","fromNodeId":"fob-inventory","toNodeId":"fob-mrp-spk","expectedDataType":"StandardHandoffPayload","isFeedbackReworkLoop":false},{"edgeId":"edge-fob-costing-hpp-to-fob-mrp-spk","fromNodeId":"fob-costing-hpp","toNodeId":"fob-mrp-spk","expectedDataType":"StandardHandoffPayload","isFeedbackReworkLoop":false},{"edgeId":"edge-fob-mrp-spk-to-fob-operator-exec","fromNodeId":"fob-mrp-spk","toNodeId":"fob-operator-exec","expectedDataType":"StandardHandoffPayload","isFeedbackReworkLoop":false},{"edgeId":"edge-fob-operator-exec-to-fob-qc-defect","fromNodeId":"fob-operator-exec","toNodeId":"fob-qc-defect","expectedDataType":"StandardHandoffPayload","isFeedbackReworkLoop":false},{"edgeId":"edge-fob-qc-defect-to-fob-fulfillment","fromNodeId":"fob-qc-defect","toNodeId":"fob-fulfillment","expectedDataType":"StandardHandoffPayload","isFeedbackReworkLoop":false},{"edgeId":"rework-fob-qc-defect-to-fob-inventory","fromNodeId":"fob-qc-defect","toNodeId":"fob-inventory","expectedDataType":"DefectReworkPayload","isFeedbackReworkLoop":true},{"edgeId":"rework-fob-qc-defect-to-fob-operator-exec","fromNodeId":"fob-qc-defect","toNodeId":"fob-operator-exec","expectedDataType":"DefectReworkPayload","isFeedbackReworkLoop":true}]}'::jsonb,
    updated_at = CURRENT_TIMESTAMP
WHERE id = 'pipe-ten-demo-001';

